mapper.select:
select * from wms_return where bool_delete_enum = 0
and bool_real_return = #{boolRealReturn}
and basic_class = #{basicClass}
and serial_number like CONCAT('%', #{serialNumber},'%')
and review_status = #{reviewStatus}
and create_time > #{createTime[0]}
and create_time < #{createTime[1]}
and (applicant_name like CONCAT('%', #{operatorName},'%') or reviewer_name like CONCAT('%', #{operatorName},'%') or editor_name like CONCAT('%', #{operatorName},'%'))
and project_ids is null
and project_ids IS NOT NULL
and find_in_set(#{projectId},project_ids)

SELECT wms_return_detail.id, wms_return.id returnId, wms_return_detail.create_time, wms_return.applicant_name, wms_return_detail.thickness, wms_return_detail.specification, wms_return_detail.area, wms_return_detail.create_time, wms_return_detail.workshop_id, wms_return_detail.nest_surplus_code, wms_return_detail.classify_id, wms_return_detail.mete, wms_return.review_status, wms_return_detail.dxf_url, wms_return_detail.img_url FROM wms_return_detail wms_return_detail LEFT JOIN wms_return wms_return ON wms_return_detail.return_id = wms_return.id WHERE wms_return_detail.bool_delete_enum = 0
AND wms_return_detail.bool_nest_surplus =#{boolNestSurplus}
AND wms_return.review_status = #{reviewStatus}
